patch.extend = function()
  -- Variables globales para tocar en vivo desde la consola
  OLA = {vel = 0.11, prof = 1.0}
  LFO = {vel = 5.7, prof = 1.0}
  RUIDO = {vel = 0.13, prof = 1.0}
  PASEO = {vel = 0.24, prof = 1.0}
  
  -- Funcion crear (sin el cable, el cable lo hacemos al final)
  local function crear(n, d)
    pcall(function() S[n] = nil end)
    S[n] = d
  end
  
  -- Atajos para ahorrar caracteres
  local TP = 2 * math.pi
  local sin, cos, rnd = math.sin, math.cos, math.random
  local f1, f2, f3, a, b, x = 0, 0, 0, 0, 0, 0
  local s = {0, 0, 0, 0, 0}
  
  -- Modulos (Mantenemos el + -1 para evitar el bug del Atrium)
  crear("ola", {gen_poly = function(dt)
    f1 = (f1 + OLA.vel * dt / 1000) % 1
    for v = 0, 4 do s[v + 1] = sin(TP * (f1 + v / 5)) * OLA.prof end
    return s
  end})
  
  crear("lfo_seno", {gen = function(dt)
    f2 = (f2 + LFO.vel * dt / 1000) % 1
    return sin(TP * f2) * LFO.prof
  end})
  
  crear("ruido_suave", {gen = function(dt)
    f3 = f3 + RUIDO.vel * dt / 1000
    while f3 >= 1 do
      f3 = f3 + -1
      a = b
      b = rnd() * 2 + -1
    end
    return (a + (b + -a) * ((1 + -cos(math.pi * f3)) / 2)) * RUIDO.prof
  end})
  
  crear("paseo", {gen = function(dt)
    x = x + (rnd() * 2 + -1) * 0.0005 * dt * PASEO.vel
    if x > 1 then x = 1 elseif x < -1 then x = -1 end
    return x * PASEO.prof
  end})

  -- === CABLES (Como indico Claudis, dentro de extend) ===
  local L = Map.link
  
  pcall(L, "ola", 0.24, "sustain")
  pcall(L, "lfo_seno", 0.01, "tone")
  pcall(L, "paseo", 0.3, "notes")
  
  -- Ejemplo de multiples destinos para el ruido:
  pcall(L, "ruido_suave", 0.7, "spectre2")
  pcall(L, "lfo_seno", 0.02, "spectre1")
  pcall(L, "paseo", -0.5, "energy")
  pcall(L, "paseo", 0.7, "tone")
end

